const __vite__mapDeps=(i,m=__vite__mapDeps,d=(m.f||(m.f=["assets/DevanagariWriter-TlJeelzQ.js","assets/rolldown-runtime-XKyaHtl9.js","assets/vendor-framer-HPtay4w-.js","assets/index-Dy_4qWHW.js","assets/vendor-three-DMppALgn.js","assets/vendor-lenis-DYAF5LSz.js","assets/vendor-gsap-CHfANB6y.js","assets/index-BCD4czU6.css","assets/useInView-6t3WHOAv.js","assets/ShowpieceCh1Opening-BbvvSyD4.js"])))=>i.map(i=>d[i]);
import{r as e}from"./rolldown-runtime-XKyaHtl9.js";import{i as t,r as n,t as r}from"./vendor-framer-HPtay4w-.js";import{n as i,t as a}from"./index-Dy_4qWHW.js";import{t as o}from"./useInView-6t3WHOAv.js";import{t as s}from"./LazyViewport-CT0c0XP7.js";import{t as c}from"./verses-Egs9pT8l.js";import{t as l}from"./ContinueBar-Bs_KI4wN.js";import{t as u}from"./FullWidthVerseBand-k2qLPXXo.js";import{t as d}from"./DevanagariScenery-Dy33Hxvi.js";var f=e(t(),1),p={id:0,devanagariNumeral:`०`,title:`Invocation`,subtitle:`Śānti Pāṭha — The Peace Chants That Open the Way`,sanskritTitle:`शान्तिपाठः`,epigraph:`ॐ सह नाववतु। सह नौ भुनक्तु। — May we be protected together. May we be nourished together.`,content:[{type:`prose`,text:`Every traditional recitation of the Upanishads begins not with argument but with prayer. Before a single philosophical proposition is uttered, teacher and student pause to chant the Śānti Pāṭha — the peace invocation. This is not ornamental. In the Indian pedagogical tradition, the invocation performs a precise function: it creates a shared container of safety, intention, and receptivity. It marks the threshold between ordinary discourse and sacred inquiry.`},{type:`prose`,text:`The Taittirīya Upaniṣad opens with the well-known invocation: 'Saha nāvavatu, saha nau bhunaktu, saha vīryaṃ karavāvahai' — 'May [Brahman] protect us both, may It nourish us both, may we work together with vigour.' The prayer is in the dual number (dvivacana), a grammatical form that binds teacher and student into a single unit of shared endeavour. As the Indologist Patrick Olivelle notes in his translation (1996), these invocations establish the relational frame within which the Upanishadic teaching unfolds. The guru-śiṣya relationship is not hierarchical command but mutual exploration, and the invocation consecrates that mutuality.`},{type:`verse_ref`,verseId:`taittiriya-2-0-1`},{type:`prose`,text:`A second great invocation comes from the Bṛhadāraṇyaka / Īśā tradition: 'Om pūrṇam adaḥ pūrṇam idaṃ, pūrṇāt pūrṇam udacyate; pūrṇasya pūrṇam ādāya pūrṇam evāvaśiṣyate' — 'That is whole; this is whole. From wholeness, wholeness arises. When wholeness is taken from wholeness, wholeness alone remains.' Śaṅkara, in his commentary (Bhāṣya) on the Īśā Upaniṣad, interprets 'pūrṇa' here as the infinite, self-complete nature of Brahman — that which cannot be diminished by any subtraction or division. In terms of resilience, this verse offers a remarkable proposition: the deepest ground of the self is not a resource that depletes. Unlike willpower models in psychology (cf. Baumeister's ego-depletion hypothesis, now debated), the Upanishadic self is posited as inherently whole — pūrṇa — regardless of what is 'taken' from it by circumstance.`},{type:`verse_ref`,verseId:`isha-purna`},{type:`prose`,text:`What do these invocations accomplish psychologically? At minimum, three things. First, they serve as a transition ritual — what the psychologist Arnold van Gennep (1909) called a 'liminal' passage, moving participants from the mundane into a space of heightened attention. Second, they establish collective safety. The repeated use of 'together' (saha) signals that the inquiry ahead, which will confront mortality, fear, and the limits of the self, will be undertaken in companionship. Third, they set an intention of non-hostility: 'mā vidviṣāvahai' — 'May we not be hostile to one another.' Learning about the deepest truths of existence requires vulnerability, and vulnerability requires the absence of threat.`},{type:`prose`,text:`For this project, these invocations set the frame for everything that follows. We approach the Upanishads not as relics but as living dialogues — texts composed in a world of ritual fire and forest hermitages, yet asking questions that modern psychology has only recently begun to formulate in its own idiom. We do so with scholarly care, acknowledging the interpretive traditions that have shaped these texts over two millennia, and with humility about the limits of cross-cultural comparison.`},{type:`resilience_insight`,title:`The Container Before the Content`,text:`Resilience research consistently emphasises the role of felt safety in enabling adaptive coping. Porges's polyvagal theory (2011) proposes that the autonomic nervous system must first detect safety before higher cognitive processes — reflection, meaning-making — become accessible. The Śānti Pāṭha performs an analogous function: by ritually establishing peace and mutual goodwill, it creates the relational safety within which the most challenging questions about suffering, death, and identity can be explored without overwhelm.`},{type:`modern_parallel`,title:`Ritual and Psychological Readiness`,text:`Modern therapeutic practice often begins with grounding exercises — breathing techniques, body scans, or the explicit statement of ground rules. Trauma-informed pedagogy (as articulated by Judith Herman, 1992) insists that safety must precede exploration of painful material. The Upanishadic invocation can be read as an ancient instance of this principle: you do not plunge into existential inquiry without first preparing the ground. This parallel is suggestive, not causal — the Upanishadic ṛṣis were not psychotherapists. But the structural similarity is worth noting.`},{type:`reflect`,prompt:`Before you read further, pause. What would it mean for you to begin an inquiry into your own resilience from a place of 'saha' — togetherness — rather than solitary self-improvement? What kind of safety do you need in order to honestly examine how you face difficulty?`}],sources:[`Taittirīya Upaniṣad, Śīkṣā Vallī (invocation)`,`Īśā Upaniṣad (Śānti Pāṭha: pūrṇam adaḥ)`,`Olivelle, Patrick. Upaniṣads. Oxford University Press, 1996.`,`Śaṅkara. Īśā Upaniṣad Bhāṣya.`,`Porges, Stephen. The Polyvagal Theory. W.W. Norton, 2011.`,`Herman, Judith. Trauma and Recovery. Basic Books, 1992.`,`van Gennep, Arnold. The Rites of Passage. 1909.`],wordCount:620},m={id:1,devanagariNumeral:`१`,title:`What Is Resilience?`,subtitle:`Two Maps of the Mind — Modern Psychology and the Upanishadic Tradition`,sanskritTitle:`धैर्यम् किम्`,epigraph:`Resilience is not the absence of distress but the ability to move through it. — Adapted from Bonanno, 2004`,content:[{type:`prose`,text:`The word 'resilience' entered psychological science from materials engineering: a resilient material is one that, when deformed by stress, returns to its original shape. The metaphor, as Ann Masten observed in her landmark 2001 paper, has both utility and limits. Human resilience is not mere return to baseline. It is, in her phrase, 'ordinary magic' — the remarkably common capacity of people to adapt positively in the face of adversity, drawing on everyday cognitive and emotional resources rather than rare heroic traits.`},{type:`prose`,text:`Modern resilience research has passed through several generations. The first generation, emerging from studies of children of parents with schizophrenia (Garmezy, 1974) and survivors of extreme poverty (Werner & Smith, 1982), asked: who survives? The second generation asked: what processes enable survival? Key frameworks emerged. Viktor Frankl (1946), writing from the abyss of Auschwitz, proposed that meaning — the capacity to find purpose even in suffering — is the irreducible core of psychological survival. His logotherapy holds that humans can endure almost anything if they can answer the question 'why.' Martin Seligman's PERMA model (2011) proposed five pillars of flourishing: Positive Emotion, Engagement, Relationships, Meaning, and Accomplishment. George Bonanno (2004) challenged earlier stage models of grief by demonstrating that the most common trajectory after loss is not prolonged distress followed by recovery, but stable, ongoing functionality — a finding that surprised the field. Tedeschi and Calhoun (2004) introduced the concept of post-traumatic growth: the possibility that struggle with highly challenging circumstances can produce positive psychological changes, including deepened relationships, new possibilities, greater personal strength, spiritual development, and enhanced appreciation for life.`},{type:`prose`,text:`These frameworks share a common architecture. They presuppose a self that is buffeted by external stressors, possesses internal and relational resources, and either maintains equilibrium or transforms through the encounter with adversity. Resilience, in these models, is fundamentally relational and processual — it is not a trait one 'has' but a pattern one enacts over time, in context.`},{type:`prose`,text:`The Upanishadic tradition offers a structurally different map. In the principal Upanishads (those commented upon by Śaṅkara, roughly the 10–13 oldest texts), the question is not 'how does the self cope with adversity?' but 'what is the self that seems to suffer?' The Upanishadic answer, across diverse formulations, converges on a radical claim: the deepest self (Ātman) is identical with the ground of all reality (Brahman), and this self is by nature unborn, undying, and beyond the reach of suffering. The Kaṭha Upaniṣad declares: 'The Ātman is not born, nor does it die. It did not come from anywhere, nor did it become anything. Unborn, eternal, everlasting, ancient — it is not slain when the body is slain' (1.2.18, author's rendering). Śaṅkara's Advaita Vedānta reads this as an ontological statement: suffering belongs to the domain of appearances (vyāvahārika), not ultimate reality (pāramārthika).`},{type:`verse_ref`,verseId:`katha-1-2-18`},{type:`prose`,text:`This is a fundamentally different theory of resilience. Where modern psychology asks how the empirical self adapts, the Upanishads ask the inquirer to investigate whether the self that suffers is the real self at all. The resilient individual, in Upanishadic terms, is not the one who bounces back from difficulty but the one who recognises that their deepest identity was never the thing that was deformed. Radhakrishnan (1953) paraphrases this stance: 'When we know the Self, we transcend sorrow, for sorrow belongs to the not-Self.' This is not escapism — Śaṅkara himself insists that empirical duties remain fully binding — but a reframing of the ontological status of adversity.`},{type:`prose`,text:`A comparison may be helpful, with the crucial caveat that these traditions arise from radically different epistemologies and cultural contexts, and any comparison risks flattening both. The following table is offered not as an equation but as a heuristic for thinking across traditions.`},{type:`prose`,text:`Modern Psychology locates the self in biographical and embodied experience, defines resilience as adaptive functioning despite adversity, and prescribes strategies such as cognitive reappraisal, social support, and meaning-making. The Upanishadic tradition locates the self in Ātman (beyond biography), defines resilience as recognition that the true Self is untouched by suffering, and prescribes practices of self-inquiry (ātma-vicāra), discrimination (viveka), and endurance (titikṣā). Modern psychology is empirical and falsifiable; the Upanishadic tradition is experiential and revelatory (śruti). Both recognise the centrality of meaning; both affirm that resilience is a practice, not merely a trait.`},{type:`resilience_insight`,title:`Two Kinds of Resilience — or One?`,text:`Modern psychology describes resilience as a process that unfolds within the empirical self — the person with a history, a body, relationships, and vulnerabilities. The Upanishads describe a resilience that is grounded in the recognition of a self beyond the empirical — the Ātman that is, in Śaṅkara's reading, never actually wounded. These need not be seen as contradictory. One might read them as operating at different levels of analysis: the pragmatic (how do I cope today?) and the existential (what am I, ultimately, that suffers?). This project explores their dialogue without collapsing the distance between them.`},{type:`modern_parallel`,title:`Frankl and the Upanishadic Seer`,text:`Frankl's insight from the concentration camps — that the last of human freedoms is the ability to choose one's attitude in any given set of circumstances — resonates with the Upanishadic emphasis on the witness-self that observes but is not destroyed by experience. Frankl himself was influenced by existentialism rather than Indian philosophy, and the parallel should not be overstated. But both traditions converge on the proposition that meaning, or recognition of what is ultimately real, is the hinge of resilience. The difference is that Frankl locates meaning in personal commitment (to a task, a person, a value), while the Upanishadic tradition locates it in ontological recognition (of one's identity with the imperishable).`},{type:`prose`,text:`A final caution. This project does not claim that the Upanishads 'predicted' modern psychology or that modern psychology 'validates' the Upanishads. These are incommensurable discourses with different rules of evidence, different conceptions of the self, and different goals. The Upanishadic ṛṣis sought mokṣa — liberation from the cycle of rebirth. Modern psychologists seek measurable improvements in well-being and functioning. What we do claim is that a careful, honest dialogue between these traditions can be illuminating for both — and that the Upanishads contain resources for thinking about human suffering and strength that deserve wider engagement outside specialist Indology.`},{type:`reflect`,prompt:`Consider a time when you faced significant difficulty. Did your sense of 'who you are' shift during that experience — or did some part of you feel unchanged beneath the turmoil? What would it mean to take that unchanging part seriously as the foundation of your resilience?`}],sources:[`Masten, Ann. 'Ordinary Magic: Resilience Processes in Development.' American Psychologist 56.3 (2001): 227–238.`,`Bonanno, George. 'Loss, Trauma, and Human Resilience.' American Psychologist 59.1 (2004): 20–28.`,`Frankl, Viktor. Man's Search for Meaning. 1946.`,`Seligman, Martin. Flourish. Free Press, 2011.`,`Tedeschi, R.G. & Calhoun, L.G. 'Posttraumatic Growth: Conceptual Foundations and Empirical Evidence.' Psychological Inquiry 15.1 (2004): 1–18.`,`Kaṭha Upaniṣad 1.2.18`,`Śaṅkara. Kaṭha Upaniṣad Bhāṣya.`,`Radhakrishnan, S. The Principal Upanishads. George Allen & Unwin, 1953.`,`Werner, E. & Smith, R. Vulnerable but Invincible. McGraw-Hill, 1982.`,`Olivelle, Patrick. Upaniṣads. Oxford University Press, 1996.`],wordCount:1020},h=n();function g(){return(0,h.jsxs)(`svg`,{width:`60`,height:`60`,viewBox:`0 0 60 60`,fill:`none`,className:`glow-gold`,children:[(0,h.jsx)(`circle`,{cx:`30`,cy:`30`,r:`28`,stroke:`var(--gold)`,strokeWidth:`0.5`,opacity:`0.4`}),(0,h.jsx)(`circle`,{cx:`30`,cy:`30`,r:`24`,stroke:`var(--gold)`,strokeWidth:`0.5`,opacity:`0.3`}),Array.from({length:8}).map((e,t)=>{let n=t/8*Math.PI*2,r=30+Math.cos(n)*10,i=30+Math.sin(n)*10,a=30+Math.cos(n)*22,o=30+Math.sin(n)*22;return(0,h.jsx)(`ellipse`,{cx:(r+a)/2,cy:(i+o)/2,rx:`6`,ry:`3`,fill:`var(--gold)`,opacity:`0.15`,transform:`rotate(${t/8*360} ${(r+a)/2} ${(i+o)/2})`},t)}),(0,h.jsx)(`circle`,{cx:`30`,cy:`30`,r:`4`,fill:`var(--gold)`,opacity:`0.3`}),(0,h.jsx)(`circle`,{cx:`30`,cy:`30`,r:`2`,fill:`var(--saffron)`,opacity:`0.5`})]})}function _(){return(0,h.jsxs)(`svg`,{width:`50`,height:`30`,viewBox:`0 0 50 30`,fill:`none`,children:[(0,h.jsx)(`path`,{d:`M25 28 C20 22 10 18 8 10 C6 4 14 2 25 8 C36 2 44 4 42 10 C40 18 30 22 25 28Z`,fill:`var(--lotus)`,opacity:`0.2`}),(0,h.jsx)(`path`,{d:`M25 26 C22 20 16 16 14 12 C12 8 18 6 25 10 C32 6 38 8 36 12 C34 16 28 20 25 26Z`,fill:`var(--lotus)`,opacity:`0.3`}),(0,h.jsx)(`path`,{d:`M25 22 C23 18 20 16 18 14 C16 12 20 10 25 13 C30 10 34 12 32 14 C30 16 27 18 25 22Z`,fill:`var(--lotus)`,opacity:`0.4`})]})}function v(){return(0,h.jsx)(`span`,{className:`sanskrit text-2xl`,style:{color:`var(--gold)`,opacity:.4},children:`ॐ`})}